export const FLAVORS=[{name:'Picante',color:'Vermelho',hex:'#d45b55',battle:'Ataque',contest:'Carisma',dice:true},{name:'Seco',color:'Azul',hex:'#638fd5',battle:'At. especial',contest:'Beleza',dice:true},{name:'Doce',color:'Rosa',hex:'#d87caf',battle:'Evasão',contest:'Fofura'},{name:'Amargo',color:'Verde',hex:'#69a278',battle:'Def. especial',contest:'Esperteza'},{name:'Azedo',color:'Amarelo',hex:'#ddbc55',battle:'Defesa',contest:'Vigor'}];
export function potency(score){return score<20?0:score<40?2:score<100?3:4;}
export function cookingHours(score){if(!Number.isInteger(score))throw Error('Informe o resultado inteiro do teste de Culinária.');return score<12?0:score<=16?1:score<=21?2:3;}
export function flavorTotals(ingredients){return FLAVORS.map((_,i)=>ingredients.reduce((sum,b)=>sum+(b?.flavors?.[i]||0),0));}
export function flavorOptions(totals,mode){const sorted=totals.slice().sort((a,b)=>b-a);if(mode==='single')return totals.flatMap((v,i)=>v>0&&v===sorted[0]?[[i]]:[]);const list=[];for(let i=0;i<5;i++)for(let j=i+1;j<5;j++)if(totals[i]>0&&totals[j]>0&&totals[i]+totals[j]===sorted[0]+sorted[1])list.push([i,j]);return list;}
export function describeBlock(block){if(!block.hours||!block.potency)return {battle:'Sem benefício especial',contest:'Sem benefício especial'};return {battle:block.flavors.map((f,i)=>`+${block.allocation[i]}${FLAVORS[f].dice?'d4':''} ${FLAVORS[f].battle}`).join(' · '),contest:block.flavors.map((f,i)=>`+${block.allocation[i]} ${FLAVORS[f].contest}`).join(' · ')};}
export function blockColor(flavors){return flavors.length===2&&flavors.includes(0)&&flavors.includes(1)?'Roxo':flavors.map(i=>FLAVORS[i].color).join(' + ');}
export function blockRecipe(ingredients,mode,chosen,allocation,result){
 if(ingredients.length!==3||ingredients.some(b=>b?.category!=='Berries'||!Array.isArray(b.flavors)||b.flavors.length!==5||b.flavors.some(n=>!Number.isFinite(n)||n<0)))throw Error('Selecione três Berries com sabores cadastrados.');
 if(!['single','double'].includes(mode))throw Error('Escolha cor única ou dupla.');
 const totals=flavorTotals(ingredients),options=flavorOptions(totals,mode);if(!options.some(o=>o.join(',')===chosen.join(',')))throw Error('Escolha entre os sabores mais intensos da mistura.');
 const score=chosen.reduce((n,i)=>n+totals[i],0),power=potency(score),hours=cookingHours(result);
 if(allocation.length!==chosen.length||allocation.some(n=>!Number.isInteger(n)||n<(power&&mode==='double'?1:0))||allocation.reduce((a,b)=>a+b,0)!==power)throw Error('Distribua todos os pontos de potência entre os sabores escolhidos.');
 return {ingredients:ingredients.map(i=>i.id),totals,mode,flavors:[...chosen],allocation:[...allocation],score,potency:power,testResult:result,hours,color:blockColor(chosen),quality:hours===0?'Preparo comum':hours===1?'Bom Pokéblock':hours===2?'Excelente Pokéblock':'Pokéblock excepcional',rulesVersion:1};
}
export function prepareBlock(state,catalog,draft){const ingredients=draft.ingredients.map(id=>catalog.find(i=>i.id===id)),recipe=blockRecipe(ingredients,draft.mode,draft.flavors,draft.allocation,draft.result),counts={};for(const id of draft.ingredients)counts[id]=(counts[id]||0)+1;for(const[id,qty]of Object.entries(counts)){const entry=state.inventory.find(e=>e.id===id),reserved=state.pokemon.filter(p=>p.held===id).length;if(!entry||entry.qty-reserved<qty)throw Error('Não há Berries disponíveis suficientes para esta receita.');}for(const[id,qty]of Object.entries(counts))state.inventory.find(e=>e.id===id).qty-=qty;const block={...recipe,id:crypto.randomUUID(),qty:1};(state.pokeblocks ||= []).push(block);return block;}
export function hasEquipment(state,catalog,feature,enforce=false){if(!enforce)return true;return state.inventory.some(e=>e.qty>0&&catalog.find(i=>i.id===e.id)?.features?.includes(feature));}
